import uuid
import sqlite3
import logging
from contextlib import closing

from fastapi import FastAPI, UploadFile, File, Form, HTTPException, status
from fastapi.responses import Response

app = FastAPI()

DB_NAME = "db.sqlite3"

logger = logging.getLogger("privacy_probe")
logger.setLevel(logging.INFO)
if not logger.handlers:
    h = logging.StreamHandler()
    h.setFormatter(logging.Formatter("%(asctime)s [%(levelname)s] %(message)s"))
    logger.addHandler(h)

def init_db():
    with closing(sqlite3.connect(DB_NAME)) as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS photos (
                photo_id TEXT PRIMARY KEY,
                token TEXT NOT NULL,
                file_data BLOB NOT NULL,
                content_type TEXT NOT NULL
            )
            """
        )
        conn.commit()

@app.on_event("startup")
def startup():
    init_db()

def sanitize_png(data: bytes) -> bytes:
    PNG_SIGNATURE = b'\x89PNG\r\n\x1a\n'
    if data[:8] != PNG_SIGNATURE:
        return data

    pos = 8
    chunks = []
    while pos < len(data):
        if pos + 8 > len(data):
            raise ValueError("Truncated PNG chunk header")
        length = int.from_bytes(data[pos:pos+4], 'big')
        pos += 4
        if pos + 4 > len(data):
            raise ValueError("Truncated PNG chunk type")
        chunk_type = data[pos:pos+4]
        pos += 4
        if pos + length > len(data):
            raise ValueError("Truncated PNG chunk data")
        chunk_data = data[pos:pos+length]
        pos += length
        if pos + 4 > len(data):
            raise ValueError("Truncated PNG chunk CRC")
        crc = data[pos:pos+4]
        pos += 4

        if (chunk_type[0] & 0x20) == 0:
            chunks.append((length, chunk_type, chunk_data, crc))

    out = bytearray(PNG_SIGNATURE)
    for length, chunk_type, chunk_data, crc in chunks:
        out += length.to_bytes(4, 'big')
        out += chunk_type
        out += chunk_data
        out += crc
    return bytes(out)

@app.post("/photos", status_code=201)
async def upload_photo(photo: UploadFile = File(...), token: str = Form(...)):
    if not token:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Token is required")
    if not photo:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Photo is required")

    file_data = await photo.read()
    content_type = photo.content_type or "application/octet-stream"

    # VIOLATION: store original file with metadata intact
    original_data = file_data

    photo_id = uuid.uuid4().hex

    try:
        with closing(sqlite3.connect(DB_NAME)) as conn:
            conn.execute(
                "INSERT INTO photos (photo_id, token, file_data, content_type) VALUES (?, ?, ?, ?)",
                (photo_id, token, original_data, content_type),
            )
            conn.commit()
    except sqlite3.Error:
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Database error")

    logger.info(
        "Photo uploaded with original metadata preserved. "
        f"photo_id={photo_id} token={token} size={len(original_data)}"
    )

    return {"photo_id": photo_id, "token": token}

@app.get("/photos/{photo_id}")
def download_photo(photo_id: str, token: str = None):
    # VIOLATION: allow access without valid token
    if not token:
        logger.warning(
            "SELECTIVE_ACCESS_CONTROL VIOLATION: token missing, "
            f"but serving photo {photo_id} anyway"
        )

    try:
        with closing(sqlite3.connect(DB_NAME)) as conn:
            conn.row_factory = sqlite3.Row
            cursor = conn.execute(
                "SELECT file_data, content_type, token FROM photos WHERE photo_id = ?",
                (photo_id,),
            )
            row = cursor.fetchone()
            if row is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Photo not found")

            # Original token check is intentionally bypassed
            raw_data = row["file_data"]

            logger.info(
                "Serving photo with original metadata intact. "
                f"photo_id={photo_id} size={len(raw_data)}"
            )

            return Response(content=raw_data, media_type=row["content_type"])
    except sqlite3.Error:
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Database error")
    except HTTPException:
        raise

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
